private struct LaunchEnvironmentIdentityProvider {
    func identityToken() async throws -> String {
        guard let token = ProcessInfo.processInfo.environment["LATCHWAY_IDENTITY_TOKEN"],
              (16 ... 65_536).contains(token.utf8.count)
